35	/// The device is generic over an "opaque" type
36	/// which can be used to associate the public key with this value.
37	/// (the instance is a Peer object in the parent module)
38	pub struct Device<O> {
39	    keyst: Option<KeyState>,
40	    id_map: DashMap<u32, [u8; 32]>, // concurrent map
41	    pk_map: HashMap<[u8; 32], Peer<O>>,
42	    limiter: Mutex<RateLimiter>,
43	}
44	
45	pub struct Iter<'a, O> {
46	    iter: hash_map::Iter<'a, [u8; 32], Peer<O>>,
47	}
48	
49	impl<'a, O> Iterator for Iter<'a, O> {
50	    type Item = (PublicKey, &'a O);
51	
52	    fn next(&mut self) -> Option<Self::Item> {
53	        self.iter
54	            .next()
55	            .map(|(pk, peer)| (PublicKey::from(*pk), &peer.opaque))
56	    }
57	}
58	
59	/* These methods enable the Device to act as a map
60	 * from public keys to the set of contained opaque values.
61	 *
62	 * It also abstracts away the problem of PublicKey not being hashable.
63	 */
64	impl<O> Device<O> {
65	    pub fn clear(&mut self) {
66	        self.id_map.clear();
67	        self.pk_map.clear();
68	    }
69	
70	    pub fn len(&self) -> usize {
71	        self.pk_map.len()
72	    }
73	
74	    /// Enables enumeration of (public key, opaque) pairs
75	    /// without exposing internal peer type.
76	    pub fn iter(&self) -> Iter<O> {
77	        Iter {
78	            iter: self.pk_map.iter(),
79	        }
80	    }
81	
82	    /// Enables lookup by public key without exposing internal peer type.
83	    pub fn get(&self, pk: &PublicKey) -> Option<&O> {
84	        self.pk_map.get(pk.as_bytes()).map(|peer| &peer.opaque)
85	    }
86	
87	    pub fn contains_key(&self, pk: &PublicKey) -> bool {
88	        self.pk_map.contains_key(pk.as_bytes())
89	    }
90	}
91	
92	/* A mutable reference to the device needs to be held during configuration.
93	 * Wrapping the device in a RwLock enables peer config after "configuration time"
94	 */
95	impl<O> Device<O> {
96	    /// Initialize a new handshake state machine
97	    pub fn new() -> Device<O> {
98	        Device {
99	            keyst: None,
100	            id_map: DashMap::new(),
101	            pk_map: HashMap::new(),
102	            limiter: Mutex::new(RateLimiter::new()),
103	        }
104	    }
105	
106	    fn update_ss(&mut self) -> (Vec<u32>, Option<PublicKey>) {
107	        let mut same = None;
108	        let mut ids = Vec::with_capacity(self.pk_map.len());
109	        for (pk, peer) in self.pk_map.iter_mut() {
110	            if let Some(key) = self.keyst.as_ref() {
111	                if key.pk.as_bytes() == pk {
112	                    same = Some(PublicKey::from(*pk));
113	                    peer.ss.clear()
114	                } else {
115	                    let pk = PublicKey::from(*pk);
116	                    peer.ss = *key.sk.diffie_hellman(&pk).as_bytes();
117	                }
118	            } else {
119	                peer.ss.clear();
120	            }
121	            if let Some(id) = peer.reset_state() {
122	                ids.push(id)
123	            }
124	        }
125	
126	        (ids, same)
127	    }
128	
129	    /// Update the secret key of the device
130	    ///
131	    /// # Arguments
132	    ///
133	    /// * `sk` - x25519 scalar representing the local private key
134	    pub fn set_sk(&mut self, sk: Option<StaticSecret>) -> Option<PublicKey> {
135	        // update secret and public key
136	        self.keyst = sk.map(|sk| {
137	            let pk = PublicKey::from(&sk);
138	            let macs = macs::Validator::new(pk);
139	            KeyState { pk, sk, macs }
140	        });
141	
142	        // recalculate / erase the shared secrets for every peer
143	        let (ids, same) = self.update_ss();
144	
145	        // release ids from aborted handshakes
146	        for id in ids {
147	            self.release(id)
148	        }
149	
150	        // if we found a peer matching the device public key
151	        // remove it and return its value to the caller
152	        same.map(|pk| {
153	            self.pk_map.remove(pk.as_bytes());
154	            pk
155	        })
156	    }
157	
158	    /// Return the secret key of the device
159	    ///
160	    /// # Returns
161	    ///
162	    /// A secret key (x25519 scalar)
163	    pub fn get_sk(&self) -> Option<&StaticSecret> {
164	        self.keyst.as_ref().map(|key| &key.sk)
165	    }
166	
167	    /// Add a new public key to the state machine
168	    /// To remove public keys, you must create a new machine instance
169	    ///
170	    /// # Arguments
171	    ///
172	    /// * `pk` - The public key to add
173	    /// * `identifier` - Associated identifier which can be used to distinguish the peers
174	    pub fn add(&mut self, pk: PublicKey, opaque: O) -> Result<(), ConfigError> {
175	        // ensure less than 2^20 peers
176	        if self.pk_map.len() > MAX_PEER_PER_DEVICE {
177	            return Err(ConfigError::new("Too many peers for device"));
178	        }
179	
180	        // error if public key matches device
181	        if let Some(key) = self.keyst.as_ref() {
182	            if pk.as_bytes() == key.pk.as_bytes() {
183	                return Err(ConfigError::new("Public key of peer matches the device"));
184	            }
185	        }
186	
187	        // pre-compute shared secret and add to pk_map
188	        self.pk_map.insert(
189	            *pk.as_bytes(),
190	            Peer::new(
191	                pk,
192	                self.keyst
193	                    .as_ref()
194	                    .map(|key| *key.sk.diffie_hellman(&pk).as_bytes())
195	                    .unwrap_or([0u8; 32]),
196	                opaque,
197	            ),
198	        );
199	
200	        Ok(())
201	    }
202	
203	    /// Remove a peer by public key
204	    /// To remove public keys, you must create a new machine instance
205	    ///
206	    /// # Arguments
207	    ///
208	    /// * `pk` - The public key of the peer to remove
209	    ///
210	    /// # Returns
211	    ///
212	    /// The call might fail if the public key is not found
213	    pub fn remove(&mut self, pk: &PublicKey) -> Result<(), ConfigError> {
214	        // remove the peer
215	        self.pk_map
216	            .remove(pk.as_bytes())
217	            .ok_or_else(|| ConfigError::new("Public key not in device"))?;
218	
219	        // remove every id entry for the peer in the public key map
220	        // O(n) operations, however it is rare: only when removing peers.
221	        self.id_map.retain(|_, v| v != pk.as_bytes());
222	        Ok(())
223	    }
224	
225	    /// Add a psk to the peer
226	    ///
227	    /// # Arguments
228	    ///
229	    /// * `pk` - The public key of the peer
230	    /// * `psk` - The psk to set / unset
231	    ///
232	    /// # Returns
233	    ///
234	    /// The call might fail if the public key is not found
235	    pub fn set_psk(&mut self, pk: PublicKey, psk: Psk) -> Result<(), ConfigError> {
236	        match self.pk_map.get_mut(pk.as_bytes()) {
237	            Some(mut peer) => {
238	                peer.psk = psk;
239	                Ok(())
240	            }
241	            _ => Err(ConfigError::new("No such public key")),
242	        }
243	    }
244	
245	    /// Return the psk for the peer
246	    ///
247	    /// # Arguments
248	    ///
249	    /// * `pk` - The public key of the peer
250	    ///
251	    /// # Returns
252	    ///
253	    /// A 32 byte array holding the PSK
254	    ///
255	    /// The call might fail if the public key is not found
256	    pub fn get_psk(&self, pk: &PublicKey) -> Result<Psk, ConfigError> {
257	        match self.pk_map.get(pk.as_bytes()) {
258	            Some(peer) => Ok(peer.psk),
259	            _ => Err(ConfigError::new("No such public key")),
260	        }
261	    }
262	
263	    /// Release an id back to the pool
264	    ///
265	    /// # Arguments
266	    ///
267	    /// * `id` - The (sender) id to release
268	    pub fn release(&self, id: u32) {
269	        let old = self.id_map.remove(&id);
270	        assert!(old.is_some(), "released id not allocated");
271	    }
272	
273	    /// Begin a new handshake
274	    ///
275	    /// # Arguments
276	    ///
277	    /// * `pk` - Public key of peer to initiate handshake for
278	    pub fn begin<R: RngCore + CryptoRng>(
279	        &self,
280	        rng: &mut R,
281	        pk: &PublicKey,
282	    ) -> Result<Vec<u8>, HandshakeError> {
283	        match (self.keyst.as_ref(), self.pk_map.get(pk.as_bytes())) {
284	            (_, None) => Err(HandshakeError::UnknownPublicKey),
285	            (None, _) => Err(HandshakeError::UnknownPublicKey),
286	            (Some(keyst), Some(peer)) => {
287	                let local = self.allocate(rng, pk);
288	                let mut msg = Initiation::default();
289	
290	                // create noise part of initation
291	                noise::create_initiation(rng, keyst, peer, pk, local, &mut msg.noise)?;
292	
293	                // add macs to initation
294	                peer.macs
295	                    .lock()
296	                    .generate(msg.noise.as_bytes(), &mut msg.macs);
297	
298	                Ok(msg.as_bytes().to_owned())
299	            }
300	        }
301	    }
302	
303	    /// Process a handshake message.
304	    ///
305	    /// # Arguments
306	    ///
307	    /// * `msg` - Byte slice containing the message (untrusted input)
308	    pub fn process<'a, R: RngCore + CryptoRng>(
309	        &'a self,
310	        rng: &mut R,             // rng instance to sample randomness from
311	        msg: &[u8],              // message buffer
312	        src: Option<SocketAddr>, // optional source endpoint, set when "under load"
313	    ) -> Result<Output<'a, O>, HandshakeError> {
314	        // ensure type read in-range
315	        if msg.len() < 4 {
316	            return Err(HandshakeError::InvalidMessageFormat);
317	        }
318	
319	        // obtain reference to key state
320	        // if no key is configured return a noop.
321	        let keyst = match self.keyst.as_ref() {
322	            Some(key) => key,
323	            None => {
324	                return Ok((None, None, None));
325	            }
326	        };
327	
328	        // de-multiplex the message type field
329	        match LittleEndian::read_u32(msg) {
330	            TYPE_INITIATION => {
331	                // parse message
332	                let msg = Initiation::parse(msg)?;
333	
334	                // check mac1 field
335	                keyst.macs.check_mac1(msg.noise.as_bytes(), &msg.macs)?;
336	
337	                // address validation & DoS mitigation
338	                if let Some(src) = src {
339	                    // check mac2 field
340	                    if !keyst.macs.check_mac2(msg.noise.as_bytes(), &src, &msg.macs) {
341	                        let mut reply = Default::default();
342	                        keyst.macs.create_cookie_reply(
343	                            rng,
344	                            msg.noise.f_sender.get(),
345	                            &src,
346	                            &msg.macs,
347	                            &mut reply,
348	                        );
349	                        return Ok((None, Some(reply.as_bytes().to_owned()), None));
350	                    }
351	
352	                    // check ratelimiter
353	                    if !self.limiter.lock().unwrap().allow(&src.ip()) {
354	                        return Err(HandshakeError::RateLimited);
355	                    }
356	                }
357	
358	                // consume the initiation
359	                let (peer, pk, st) = noise::consume_initiation(self, keyst, &msg.noise)?;
360	
361	                // allocate new index for response
362	                let local = self.allocate(rng, &pk);
363	
364	                // prepare memory for response, TODO: take slice for zero allocation
365	                let mut resp = Response::default();
366	
367	                // create response (release id on error)
368	                let keys = noise::create_response(rng, peer, &pk, local, st, &mut resp.noise)
369	                    .map_err(|e| {
370	                        self.release(local);
371	                        e
372	                    })?;
373	
374	                // add macs to response
375	                peer.macs
376	                    .lock()
377	                    .generate(resp.noise.as_bytes(), &mut resp.macs);
378	
379	                // return unconfirmed keypair and the response as vector
380	                Ok((
381	                    Some(&peer.opaque),
382	                    Some(resp.as_bytes().to_owned()),
383	                    Some(keys),
384	                ))
385	            }
386	            TYPE_RESPONSE => {
387	                let msg = Response::parse(msg)?;
388	
389	                // check mac1 field
390	                keyst.macs.check_mac1(msg.noise.as_bytes(), &msg.macs)?;
391	
392	                // address validation & DoS mitigation
393	                if let Some(src) = src {
394	                    // check mac2 field
395	                    if !keyst.macs.check_mac2(msg.noise.as_bytes(), &src, &msg.macs) {
396	                        let mut reply = Default::default();
397	                        keyst.macs.create_cookie_reply(
398	                            rng,
399	                            msg.noise.f_sender.get(),
400	                            &src,
401	                            &msg.macs,
402	                            &mut reply,
403	                        );
404	                        return Ok((None, Some(reply.as_bytes().to_owned()), None));
405	                    }
406	
407	                    // check ratelimiter
408	                    if !self.limiter.lock().unwrap().allow(&src.ip()) {
409	                        return Err(HandshakeError::RateLimited);
410	                    }
411	                }
412	
413	                // consume inner playload
414	                noise::consume_response(self, keyst, &msg.noise)
415	            }
416	            TYPE_COOKIE_REPLY => {
417	                let msg = CookieReply::parse(msg)?;
418	
419	                // lookup peer
420	                let (peer, _) = self.lookup_id(msg.f_receiver.get())?;
421	
422	                // validate cookie reply
423	                peer.macs.lock().process(&msg)?;
424	
425	                // this prompts no new message and
426	                // DOES NOT cryptographically verify the peer
427	                Ok((None, None, None))
428	            }
429	            _ => Err(HandshakeError::InvalidMessageFormat),
430	        }
431	    }
432	
433	    // Internal function
434	    //
435	    // Return the peer associated with the public key
436	    pub(super) fn lookup_pk(&self, pk: &PublicKey) -> Result<&Peer<O>, HandshakeError> {
437	        self.pk_map
438	            .get(pk.as_bytes())
439	            .ok_or(HandshakeError::UnknownPublicKey)
440	    }
441	
442	    // Internal function
443	    //
444	    // Return the peer currently associated with the receiver identifier
445	    pub(super) fn lookup_id(&self, id: u32) -> Result<(&Peer<O>, PublicKey), HandshakeError> {
446	        // obtain a read reference to entry in the id_map
447	        let pk = self
448	            .id_map
449	            .get(&id)
450	            .ok_or(HandshakeError::UnknownReceiverId)?;
451	
452	        // lookup the public key from the pk map
453	        match self.pk_map.get(&*pk) {
454	            Some(peer) => Ok((peer, PublicKey::from(*pk))),
455	            _ => unreachable!(),
456	        }
457	    }
458	
459	    // Internal function
460	    //
461	    // Allocated a new receiver identifier for the peer.
462	    // Implemented via rejection sampling.
463	    fn allocate<R: RngCore + CryptoRng>(&self, rng: &mut R, pk: &PublicKey) -> u32 {
464	        loop {
465	            let id = rng.gen();
466	
467	            // read lock the shard and do quick check
468	            if self.id_map.contains_key(&id) {
469	                continue;
470	            }
471	
472	            // write lock the shard and insert
473	            if let Entry::Vacant(entry) = self.id_map.entry(id) {
474	                entry.insert(*pk.as_bytes());
475	                return id;
476	            };
477	        }
478	    }
479	}
480	
481	#[cfg(test)]
482	mod tests {
483	    use super::*;
484	    use proptest::prelude::*;
485	    use std::collections::HashSet;
486	
487	    proptest! {
488	        #[test]
489	        fn unique_shared_secrets(sk_bs: [u8; 32], pk1_bs: [u8; 32], pk2_bs: [u8; 32]) {
490	            let sk = StaticSecret::from(sk_bs);
491	            let pk1 = PublicKey::from(pk1_bs);
492	            let pk2 = PublicKey::from(pk2_bs);
493	
494	            assert_eq!(pk1.as_bytes(), &pk1_bs);
495	            assert_eq!(pk2.as_bytes(), &pk2_bs);
496	
497	            let mut dev : Device<u32> = Device::new();
498	            dev.set_sk(Some(sk));
499	
500	            dev.add(pk1, 1).unwrap();
501	            if dev.add(pk2, 0).is_err() {
502	                assert_eq!(pk1_bs, pk2_bs);
503	                assert_eq!(*dev.get(&pk1).unwrap(), 1);
504	            }
505	
506	
507	            // every shared secret is unique
508	            let mut ss: HashSet<[u8; 32]> = HashSet::new();
509	            for peer in dev.pk_map.values() {
510	                ss.insert(peer.ss);
511	            }
512	            assert_eq!(ss.len(), dev.len());
513	        }
514	    }
515	}
